pol = json.load(open("/home/claude/subtasks2/6/polarity_test.json"))
sub = dict(maxrel=st["max_VUF_rel_err_pct"], nnz=st["n_VUF_nonzero"], maxiuf=st["max_IUF_abs_err_pp"], maxs=st["max_S_rel_err_pct"],
           nzero=st["n_zero"], zerovuf=st["max_zero_case_VUF_dss"], maxser=st["max_series_vs_xfmr_rel_pct"],
           czlo=-cz_rng[1], czhi=-cz_rng[0], iufcz=st["max_IUF_dss_vs_eq7_pp_caseA_CZ"], cplo=cp_rng[0], cphi=cp_rng[1],
           ci3=ci3["VUF_dss"], cp3=cp3["VUF_dss"], flip=pol["CI_B3_eq11_fixed_phasor_currents"]["VUF_flipped_teaser"],
           rowsA="\n".join(rowsA), rowsB="\n".join(rowsB))
import re
